class Solution { pair<string,int> removePattern(string text,char first,char second){string stack;int count=0;for(char letter:text)if(letter==second&&!stack.empty()&&stack.back()==first){stack.pop_back();++count;}else stack+=letter;return {stack,count};}public:int maximumGain(string text,int x,int y){if(x>=y){auto high=removePattern(text,'a','b');auto low=removePattern(high.first,'b','a');return high.second*x+low.second*y;}auto high=removePattern(text,'b','a');auto low=removePattern(high.first,'a','b');return high.second*y+low.second*x;} };
